<script setup lang="ts">
/**
 * Large title block that opens a page (`design/components/hero.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hero.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import styles from '@polymorph/recipes/structure/hero.module.css'
import Inline from '../layout/Inline.vue'

export type HeroAlign = NonNullable<HeroProps['align']>

export interface HeroProps {
  align?: 'start' | 'center'
  lede?: string
  title: string
}

defineOptions({ name: 'Hero', inheritAttrs: false })

withDefaults(defineProps<HeroProps>(), { align: 'start' })
defineSlots<{ actions?: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <section :class="styles.hero" :data-align="align" data-member="hero">
    <!-- title -->
    <h1 :class="styles.title">
      {{ title }}
    </h1>
    <!-- lede -->
    <p v-if="lede !== undefined" :class="styles.lede">
      {{ lede }}
    </p>
    <Inline
      v-if="$slots.actions"
      :gap="3"
      :wrap="true"
      :justify="align === 'center' ? 'center' : 'start'"
    >
      <slot name="actions" />
    </Inline>
  </section>
</template>
